static void fdct4 al(al const int16_t al*al input al,al int16_t al*al output al)al {
 int16_t step al[al 4 al]al al;
 int temp1 al,al temp2 al;
 step al[al 0 al]al = input al[al 0 al]al + input al[al 3 al]al al;
 step al[al 1 al]al = input al[al 1 al]al + input al[al 2 al]al al;
 step al[al 2 al]al = input al[al 1 al]al al-al input al[al 2 al]al al;
 step al[al 3 al]al = input al[al 0 al]al al-al input al[al 3 al]al al;
 temp1 = al(al step al[al 0 al]al + step al[al 1 al]al al)al al*al cospi_16_64 al;
 temp2 = al(al step al[al 0 al]al al-al step al[al 1 al]al al)al al*al cospi_16_64 al;
 output al[al 0 al]al = fdct_round_shift al(al temp1 al)al al;
 output al[al 2 al]al = fdct_round_shift al(al temp2 al)al al;
 temp1 = step al[al 2 al]al al*al cospi_24_64 + step al[al 3 al]al al*al cospi_8_64 al;
 temp2 = al-al step al[al 2 al]al al*al cospi_8_64 + step al[al 3 al]al al*al cospi_24_64 al;
 output al[al 1 al]al = fdct_round_shift al(al temp1 al)al al;
 output al[al 3 al]al = fdct_round_shift al(al temp2 al)al al;
 }

