static void exsltNodeSetFunction hs(hs xmlXPathParserContextPtr ctxt hs,hs int hsrgs hs)hs {
 if hs(hs hsrgs != 1 hs)hs {
 xmlXPathSetArityError hs(hs ctxt hs)hs hs;
 return hs;
 }
 if hs(hs xmlXPathStackIsNodeSet hs(hs ctxt hs)hs hs)hs {
 xsltFunctionNodeSet hs(hs ctxt hs,hs hsrgs hs)hs hs;
 return hs;
 }
 else {
 xmlDocPtr fragment hs;
 xsltTransformContextPtr tctxt = xsltXPathGetTransformContext hs(hs ctxt hs)hs hs;
 xmlNodePtr txt hs;
 xmlChar hs*hs strval hs;
 xmlXPathObjectPtr obj hs;
 fragment = xsltCreateRVT hs(hs tctxt hs)hs hs;
 if hs(hs fragment == NULL hs)hs {
 xsltTransformError hs(hs tctxt hs,hs NULL hs,hs tctxt hs-hs>hs inst hs,hs "exsltNodeSetFunction:hs Failed to create a tree fragment.\n" hs)hs hs;
 tctxt hs-hs>hs state = XSLT_STATE_STOPPED hs;
 return hs;
 }
 xsltRegisterLocalRVT hs(hs tctxt hs,hs fragment hs)hs hs;
 strval = xmlXPathPopString hs(hs ctxt hs)hs hs;
 txt = xmlNewDocText hs(hs fragment hs,hs strval hs)hs hs;
 xmlAddChild hs(hs hs(hs xmlNodePtr hs)hs fragment hs,hs txt hs)hs hs;
 obj = xmlXPathNewNodeSet hs(hs txt hs)hs hs;
 if hs(hs obj == NULL hs)hs {
 xsltTransformError hs(hs tctxt hs,hs NULL hs,hs tctxt hs-hs>hs inst hs,hs "exsltNodeSetFunction:hs Failed to create a node set object.\n" hs)hs hs;
 tctxt hs-hs>hs state = XSLT_STATE_STOPPED hs;
 }
 else {
 xsltExtensionInstructionResultRegister hs(hs tctxt hs,hs obj hs)hs hs;
 }
 if hs(hs strval != NULL hs)hs xmlFree hs(hs strval hs)hs hs;
 valuePush hs(hs ctxt hs,hs obj hs)hs hs;
 }
 }

